"use strict";(self.webpackChunknotes_by_sara=self.webpackChunknotes_by_sara||[]).push([["16262"],{3262(e){e.exports=JSON.parse('{"id":"F362","slug":"mmf-nav-break-the-buck","name":"Money Market Fund NAV and Breaking the Buck","subject":"Banking & Financial Institutions","section":"Banking","topic":"Shadow banking","level":"Intermediate","aliases":["shadow banking","stable NAV","run on a money fund","redemptions at par"],"formula":{"latex":"NAV=\\\\frac{A(1-\\\\ell)}{S},\\\\quad NAV_{after}=\\\\frac{A(1-\\\\ell)-wS\\\\cdot 1}{S(1-w)}","also":[],"text":"Net asset value per share = value of assets after losses / shares outstanding; If investors redeem a share fraction w at the stable price of 1.00 while the true value is lower, the NAV left for remaining holders = (assets after losses - w x shares x 1.00) / (shares x (1 - w)). The fund breaks the buck if NAV falls below 0.995"},"symbols":[{"symbol":"A","meaning":"Fund assets at market value before the loss","unit":"money"},{"symbol":"l","meaning":"Loss on assets, as a share of their value","unit":"percent"},{"symbol":"S","meaning":"Shares outstanding, issued at 1.00","unit":"shares"},{"symbol":"w","meaning":"Share of the fund redeemed at 1.00","unit":"percent"}],"when_to_use":"Use it to see why money funds and other shadow-bank vehicles are run-prone. Investors who redeem early get 1.00 while the true value is below it, so those who stay absorb the loss, which gives everyone a reason to leave first. That first-mover advantage turned small losses into a run in 2008. Rules since then allow fees and gates, and some funds now float their NAV.","worked_example":{"problem":"A fund has assets of 1,000 and 1,000 shares priced at 1.00. Its assets lose 0.6%. Then 30% of shares are redeemed at 1.00.","inputs":{"a":1000,"s":1000,"l":0.6,"w":30},"steps":[{"label":"NAV after the loss = A(1 - l) / S","working":"1000 x (1-0.006) / 1000","value":"0.9940"},{"label":"Broke the buck? (1 = yes, 0 = no)","working":"1 if 0.994<0.995 else 0","value":"1"},{"label":"NAV for remaining holders after redemptions at 1.00","working":"(1000 x (1-0.006)-0.3 x 1000 x 1) / (1000 x (1-0.3))","value":"0.9914"},{"label":"Loss per share with no redemptions","working":"1-0.994","value":"0.60%"},{"label":"Loss per share for the holders who stay","working":"1-0.991429","value":"0.86%"}],"answer":"After the loss the true NAV is 0.9940, below 0.995, so the fund has broken the buck. If 30% redeem at 1.00, the NAV of the remaining shares drops to 0.9914, a loss of 0.86% for those who stayed, versus 0.60% if no one had left."},"calculator":{"available":true,"inputs":[{"id":"a","label":"Fund assets","unit":"money","type":"number","default":1000,"hint":""},{"id":"s","label":"Shares outstanding","unit":"shares","type":"number","default":1000,"hint":""},{"id":"l","label":"Loss on assets","unit":"%","type":"number","default":0.6,"hint":""},{"id":"w","label":"Share redeemed at 1.00","unit":"%","type":"number","default":30,"hint":""}],"checks":[{"expr":"a>0 and s>0 and w<1","message":"Assets and shares must be above zero and the redemption share below 100%."}],"steps":[{"id":"nav","label":"NAV after the loss = A(1 - l) / S","expr":"a*(1-l)/s","format":"num4"},{"id":"brk","label":"Broke the buck? (1 = yes, 0 = no)","expr":"1 if nav<0.995 else 0","format":"num0"},{"id":"nav2","label":"NAV for remaining holders after redemptions at 1.00","expr":"(a*(1-l)-w*s*1)/(s*(1-w))","format":"num4"},{"id":"loss1","label":"Loss per share with no redemptions","expr":"1-nav","format":"pct2"},{"id":"loss2","label":"Loss per share for the holders who stay","expr":"1-nav2","format":"pct2"}],"results":["nav","nav2","loss2"],"percent_inputs_typed_as_whole_numbers":true,"tested_against":{"nav":0.994,"brk":1,"nav2":0.9914285714285714,"loss1":6.000000000000005e-3,"loss2":8.571428571428563e-3}},"finder":{"finds":"How redemptions at par shift losses onto remaining holders","needs":"Assets, shares, loss, redemption size"},"related":[{"slug":"bank-run-liquidity-shortfall","name":"Bank Run: Liquidity Shortfall and Fire-Sale Loss"},{"slug":"deposit-insurance-coverage","name":"Deposit Insurance Coverage and Premium"},{"slug":"stress-test-loss","name":"Stress Test Loss and Capital Buffer"}],"related_ids":["F356","F354","F380"],"group":"Money, banks and the economy","mathml":"<span class=\\"katex\\"><math xmlns=\\"http://www.w3.org/1998/Math/MathML\\" display=\\"block\\"><semantics><mrow><mi>N</mi><mi>A</mi><mi>V</mi><mo>=</mo><mfrac><mrow><mi>A</mi><mo stretchy=\\"false\\">(</mo><mn>1</mn><mo>\u2212</mo><mi mathvariant=\\"normal\\">\u2113</mi><mo stretchy=\\"false\\">)</mo></mrow><mi>S</mi></mfrac><mo separator=\\"true\\">,</mo><mspace width=\\"1em\\"/><mi>N</mi><mi>A</mi><msub><mi>V</mi><mrow><mi>a</mi><mi>f</mi><mi>t</mi><mi>e</mi><mi>r</mi></mrow></msub><mo>=</mo><mfrac><mrow><mi>A</mi><mo stretchy=\\"false\\">(</mo><mn>1</mn><mo>\u2212</mo><mi mathvariant=\\"normal\\">\u2113</mi><mo stretchy=\\"false\\">)</mo><mo>\u2212</mo><mi>w</mi><mi>S</mi><mo>\u22C5</mo><mn>1</mn></mrow><mrow><mi>S</mi><mo stretchy=\\"false\\">(</mo><mn>1</mn><mo>\u2212</mo><mi>w</mi><mo stretchy=\\"false\\">)</mo></mrow></mfrac></mrow><annotation encoding=\\"application/x-tex\\">NAV=\\\\frac{A(1-\\\\ell)}{S},\\\\quad NAV_{after}=\\\\frac{A(1-\\\\ell)-wS\\\\cdot 1}{S(1-w)}</annotation></semantics></math></span>","alsoMathml":[],"prev":{"slug":"mirr","name":"Modified Internal Rate of Return (MIRR)"},"next":{"slug":"money-multiplier","name":"Money Multiplier and Deposit Expansion"},"lesson":null,"total":522}')}}]);